#!/usr/bin/env node
/**
 * extract-components-css.mjs
 *
 * 聚合脚本：扫描指定库根目录下的 preview/component-*.html，
 * 提取每个文件 <!-- @component-css-start --> 与 <!-- @component-css-end --> 之间的 CSS，
 * 按字母顺序聚合成库根目录的 components.css。
 *
 * 行为契约（与 SKILL.md 一致）：
 *   - 仅读取标记区间内的 CSS（preview chrome 在区间外）
 *   - 顶部添加 AUTO-GENERATED 警告注释
 *   - 按文件名排序（保证输出稳定）
 *   - 跳过不包含标记的文件（warn 到 stderr，不报错）
 *
 * 用法：
 *   node extract-components-css.mjs <lib-root>
 *   node extract-components-css.mjs ./design-systems/nimbus-core
 *
 * 退出码：
 *   0 - 成功
 *   1 - 参数错误（缺 lib-root）
 *   2 - lib-root 不存在或不是目录
 *   3 - 没有任何 preview 文件
 */

import { readdir, readFile, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { join, resolve, basename, relative } from 'node:path';

/**
 * 解析命令行参数。
 *
 * @returns {string|null} 库根绝对路径；参数缺失返回 null
 */
function parseArgs() {
  const args = process.argv.slice(2);
  if (args.length === 0) {
    return null;
  }
  // 仅取第一个非 flag 参数作为 lib-root
  const positional = args.find((a) => !a.startsWith('--'));
  return positional ? resolve(positional) : null;
}

/**
 * 从 HTML 文件内容中提取 @component-css-start 与 @component-css-end 之间的 CSS。
 *
 * 实现细节：
 *   - 匹配两种写法：HTML 注释 <!-- --> 或 CSS 注释 /* *\/
 *   - 提取区间内的所有 CSS（保留原始格式与缩进）
 *   - 不在区间内时返回 null（让上层跳过）
 *
 * @param {string} htmlContent - preview HTML 全文
 * @returns {string|null} 提取的 CSS 字符串；无标记返回 null
 */
function extractComponentCss(htmlContent) {
  // 匹配 /* @component-css-start */ 与 /* @component-css-end */ 之间的内容
  // 使用 [\s\S] 匹配任意字符（含换行），非贪婪模式
  const cssCommentPattern =
    /\/\*\s*@component-css-start\s*\*\/([\s\S]*?)\/\*\s*@component-css-end\s*\*\//;

  const cssMatch = htmlContent.match(cssCommentPattern);
  if (cssMatch) {
    return cssMatch[1].trim();
  }

  // 备选：HTML 注释写法 <!-- @component-css-start --> ... <!-- @component-css-end -->
  const htmlCommentPattern =
    /<!--\s*@component-css-start\s*-->([\s\S]*?)<!--\s*@component-css-end\s*-->/;

  const htmlMatch = htmlContent.match(htmlCommentPattern);
  if (htmlMatch) {
    return htmlMatch[1].trim();
  }

  return null;
}

/**
 * 从 CSS 内容中提取组件级区块标题（如 "── Buttons ──"）。
 * 用于在聚合 CSS 中插入可读的分区注释。
 *
 * @param {string} css - 组件 CSS 内容
 * @returns {string|null} 区块标题（去装饰字符）；无则返回 null
 */
function extractSectionTitle(css) {
  // 匹配注释中的标题行，如：/* ===== Buttons ===== */ 或 /* ── Buttons ── */
  const patterns = [
    /\/\*\s*=====+\s+(.+?)\s+=+\s*\*\//,
    /\/\*\s*──+\s+(.+?)\s*──+\s*\*\//,
    /\/\*\s*==+\s+(.+?)\s*==+\s*\*\//,
  ];
  for (const pattern of patterns) {
    const match = css.match(pattern);
    if (match) {
      return match[1].trim();
    }
  }
  return null;
}

/**
 * 生成 components.css 的完整内容。
 *
 * @param {Array<{filename: string, slug: string, css: string, sectionTitle: string|null}>} components - 提取结果列表
 * @returns {string} 完整的 components.css 内容
 */
function buildAggregatedCss(components) {
  const now = new Date().toISOString();
  const header = [
    '/* ======================================================================',
    ' * components.css',
    ' *',
    ' * AUTO-GENERATED by extract-components-css.mjs — do not edit by hand.',
    ` * Generated at: ${now}`,
    ` * Source: preview/component-*.html (${components.length} files)`,
    ' *',
    ' * To regenerate after editing component CSS, run:',
    ' *   node .agents/skills/design-library-creator/scripts/extract-components-css.mjs <lib-root>',
    ' * ======================================================================',
    ' */',
    '',
  ].join('\n');

  const body = components
    .map((c) => {
      const title = c.sectionTitle || c.slug;
      const separator = '/* ' + '─'.repeat(70) + ' */';
      const heading = `/*  ${title}  (from ${c.filename})  */`;
      return [separator, heading, separator, c.css, ''].join('\n');
    })
    .join('\n');

  return header + body + '\n';
}

/**
 * 主入口。
 */
async function main() {
  const libRoot = parseArgs();
  if (!libRoot) {
    console.error('Usage: node extract-components-css.mjs <lib-root>');
    process.exit(1);
  }

  if (!existsSync(libRoot)) {
    console.error(`Error: lib-root does not exist: ${libRoot}`);
    process.exit(2);
  }

  const previewDir = join(libRoot, 'preview');
  if (!existsSync(previewDir)) {
    console.error(`Error: preview directory not found: ${previewDir}`);
    console.error(`Run /design-library-creator first to generate preview files.`);
    process.exit(2);
  }

  // 扫描 preview 目录：仅匹配 component-*.html
  const entries = await readdir(previewDir, { withFileTypes: true });
  const previewFiles = entries
    .filter((e) => e.isFile() && /^component-.+\.html$/.test(e.name))
    .map((e) => e.name)
    .sort(); // 字母顺序保证输出稳定

  if (previewFiles.length === 0) {
    console.error(`Error: no component-*.html files found in ${previewDir}`);
    process.exit(3);
  }

  console.log(`[extract-components-css] Scanning ${previewFiles.length} preview file(s)...`);

  const components = [];
  const skipped = [];

  for (const filename of previewFiles) {
    const filepath = join(previewDir, filename);
    const html = await readFile(filepath, 'utf-8');
    const css = extractComponentCss(html);

    if (!css) {
      skipped.push(filename);
      console.warn(
        `[extract-components-css] WARN: skipping ${filename} (no @component-css-start/end markers)`
      );
      continue;
    }

    // 从文件名提取 slug：component-{slug}.html → {slug}
    const slug = basename(filename, '.html').replace(/^component-/, '');
    const sectionTitle = extractSectionTitle(css);

    components.push({
      filename,
      slug,
      css,
      sectionTitle,
    });
  }

  if (components.length === 0) {
    console.error(`Error: no components extracted (all ${skipped.length} file(s) skipped)`);
    process.exit(3);
  }

  const aggregated = buildAggregatedCss(components);
  const outputPath = join(libRoot, 'components.css');
  await writeFile(outputPath, aggregated, 'utf-8');

  const relOutput = relative(process.cwd(), outputPath);
  console.log(
    `[extract-components-css] OK: ${components.length} component(s) → ${relOutput}` +
      (skipped.length > 0 ? ` (${skipped.length} skipped)` : '')
  );
  process.exit(0);
}

// 顶层 await 入口
main().catch((err) => {
  console.error('[extract-components-css] Unexpected error:', err);
  process.exit(1);
});